package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"
	"unicode"
)

func solveProblem(s string) string {
	lowerCount := 0
	higherCount := 0
	length := len(s)

	for _, r := range s {
		if unicode.IsLower(r) {
			lowerCount++
		} else {
			higherCount++
		}

		if lowerCount > length/2 {
			return strings.ToLower(s)
		}
	}

	if lowerCount == higherCount {
		return strings.ToLower(s)
	}
	return strings.ToUpper(s)
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Scan()
	s := scanner.Text()

	fmt.Println(solveProblem(s))
}

